<script>
export default {
  emits: ['updateProduct', 'closeBack'],
  props: ['isNew', 'product'],
  data () {
    return {
      modalTitle: '',
      tempProduct: {},
      isShow: false,
      category: [
        '25元青菜區',
        '50元專區',
        '特殊蔬菜區',
        '秤斤論兩區',
        '辛香配料區',
        '珍味鍋物',
        '丸子之家',
        '惠民好料理',
        '炸物最對味',
        '我想吃肉肉',
        '特價99專區',
        '海洋中的瑰寶',
        '就是想吃魚',
        '柴米油鹽',
        '健康食品',
        '調味醬料',
        '麵麵之家',
        '南北雜貨',
        '異國風味'
      ]
    }
  },
  methods: {
    upload (type) {
      let fileInput
      if (type === 'mult') {
        fileInput = document.querySelector('#file2')
      } else {
        fileInput = document.querySelector('#file')
      }
      const file = fileInput.files[0]
      const formData = new FormData()
      formData.append('file-to-upload', file)
      this.$emitter.emit('isLoading', true)
      const data = {
        username: 'jack90928@gmail.com',
        password: 'a12081616'
      }
      this.$http.post('https://vue3-course-api.hexschool.io/v2/admin/signin', data)
        .then((res) => {
          const { token } = res.data
          this.$http.defaults.headers.common.Authorization = token
          this.$http.post('https://vue3-course-api.hexschool.io/v2/api/user/check', {})
            .then(() => {
              this.$http.post('https://vue3-course-api.hexschool.io/v2/api/ginjack/admin/upload', formData)
                .then((res) => {
                  const temp = this.tempProduct
                  this.$emitter.emit('isLoading', false)
                  if (res.data.success) {
                    if (type === 'single') {
                      this.tempProduct.imageUrl = res.data.imageUrl
                    } else {
                      this.tempProduct.imagesUrl === [] ? this.tempProduct.imagesUrl = [] : this.tempProduct = temp
                      this.tempProduct.imagesUrl.push(res.data.imageUrl)
                    }
                  }
                })
                .catch(err => {
                  console.dir(err)
                })
            })
            .catch((err) => {
              console.dir(err)
              this.$router.push('/login')
            })
        })
        .catch((err) => {
          this.$emitter.emit('isLoading', false)
          const res = {
            data: {
              success: false,
              message: '使用者不存在'
            }
          }
          if (err.response.data.error.code === 'auth/user-not-found') {
            this.$httpMessageState(res, '登入')
          } else {
            res.data.message = '密碼錯誤'
            this.$httpMessageState(res, '登入')
          }
        })
    },
    openModal () {
      this.isShow = true
    },
    closeModal () {
      this.isShow = false
    }
  },
  watch: {
    product () {
      this.tempProduct = { ...this.product }
    }
  }
}
</script>

