<template>
  <div v-if="back_show" class="back-lock" @click="closeAllModal()"></div>
  <div class="content">
    <div class="admin-container d-flex jy-content-center">
      <div class="mobile-link">
        <router-link to="/admin/product">
          <span class="icon small">
            產品設定
          </span>
        </router-link>
        <router-link to="/admin/order">
          <span class="icon small">
            訂單查看
          </span>
        </router-link>
      </div>
      <div class="search w-100">
        <div class="search__input w-30">
          <div class="search__btn" @click="searchHandler()">
            <i class="fas fa-search"></i>
          </div>
          <input
            @input="searchHandler()"
            v-model.trim="searchText"
            type="text"
            class="py-2 px-2 w-100"
          >
        </div>
      </div>
      <div class="total__product w-100 d-flex align-items-center jy-content-between">
        <p>目前有 {{ products.length }} 樣商品</p>
        <a @click.prevent="openProductModal(true)" class="btn btn--success w-10" href="#">建立產品</a>
      </div>
      <div class="product w-100 mb-3">
        <ul>
          <li class="product__title d-flex jy-content-between">
            <h3 class="text-c-white f-w-bold">產品名稱</h3>
            <div class="info__group w-80">
              <ul class="d-flex fw-bold">
                <li class="w-15 d-sm-none f-w-bold">原價</li>
                <li class="w-15 f-w-bold" style="cursor: pointer">售價</li>
                <li class="w-30 f-w-bold">是否啟用</li>
                <li class="w-40 f-w-bold">編輯</li>
              </ul>
            </div>
          </li>
          <li
            v-for="item in tempProducts"
            :key="item.id"
            class="product__item d-flex jy-content-between"
            :class="{
              'bg--dark--secondary': item.is_enabled === 1,
              'bg--gray': item.is_enabled === 0
            }"
          >
            <h3>{{ item.title }}</h3>
            <div class="info__group w-80">
              <ul class="d-flex fw-bold align-items-center">
                <li class="w-15 d-sm-none">${{ $filters.thColon(item.origin_price) }}</li>
                <li class="w-15">${{ $filters.thColon(item.price) }}</li>
                <li class="d-flex jy-content-center w-30 px-4">
                  <div
                    @click="toggleProductStatus(item)"
                    class="toggle"
                    :class="{ 'active': item.is_enabled === 1 }"
                  >
                  </div>
                  <p :class="{ 'active': item.is_enabled === 1 }">
                    {{ item.is_enabled === 1 ? '啟用' : '未啟用' }}
                  </p>
                </li>
                <li class="w-40 d-flex jy-content-center flex-wrap">
                  <a
                    @click.prevent="openProductModal(false, item)"
                    class="btn btn--success w-30 mx-2"
                    href="#"
                  >
                    <i class="fas fa-edit"></i>
                  </a>
                  <a
                    @click.prevent="openDelModal('商品', item)"
                    class="btn btn--danger w-30 mx-2"
                    href="#"
                  >
                    <i class="fas fa-trash-alt"></i>
                  </a>
                </li>
              </ul>
            </div>
          </li>
        </ul>
      </div>
    </div>
    <ModalView
      ref="productModal"
      :is-new="isNew"
      :product="tempProduct"
      @update-product="updateProduct"
      @close-back="closeAllModal"
    ></ModalView>
    <DelModal
      ref="delModal"
      @del-data="delProduct"
      :data="tempProduct"
      :back="back_show"
      @close-back="closeAllModal"
    ></DelModal>
    <PageView
      :pagination="pagination"
      @get-product="changePage"
      :style="{ bg: '#1A535C', hoverBg: '#FF6B6B' }"
    ></PageView>
  </div>
</template>

<script>
import PageView from '@/components/PageNation.vue'
import ModalView from '@/components/AdminPModal.vue'
import DelModal from '@/components/AdminDelModal.vue'

export default {
  data () {
    return {
      products: [],
      tempProducts: [],
      pagination: {
        current_page: 1,
        perPage: 10,
        total_pages: 1
      },
      searchText: '',
      searchResults: null,
      tempProduct: {},
      ascending: false,
      sideToggle: true,
      isNew: false,
      back_show: false
    }
  },
  components: {
    PageView,
    ModalView,
    DelModal
  },
  methods: {
    formatProducts (productsObj) {
      return Object.values(productsObj)
    },
    getProducts () {
      this.$emitter.emit('isAdminLoading', true)
      this.$http
        .get(`${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/admin/products/all`)
        .then(({ data }) => {
          if (data.success) {
            this.products = this.formatProducts(data.products)
            this.updatePagination()
          }
          this.$emitter.emit('isAdminLoading', false)
        })
        .catch((err) => {
          this.$emitter.emit('isAdminLoading', false)
          this.$httpMessageState(err.response, '取得產品列表')
        })
    },
    updatePagination () {
      const data = this.searchResults || this.products
      this.pagination.total_pages = Math.ceil(data.length / this.pagination.perPage)
      this.pagination.has_pre = this.pagination.current_page > 1
      this.pagination.has_next = this.pagination.current_page < this.pagination.total_pages
      this.paginateProducts()
    },
    paginateProducts () {
      const data = this.searchResults || this.products
      const start = (this.pagination.current_page - 1) * this.pagination.perPage
      const end = start + this.pagination.perPage
      this.tempProducts = data.slice(start, end)
    },
    searchHandler () {
      if (this.searchText === '') {
        this.searchResults = null
      } else {
        this.searchResults = this.products.filter((product) =>
          product.title.includes(this.searchText)
        )
      }
      this.pagination.current_page = 1
      this.updatePagination()
    },
    changePage (page) {
      if (page < 1 || page > this.pagination.total_pages) {
        return // 防止越界
      }
      this.pagination.current_page = page
      this.updatePagination()
    },
    toggleProductStatus (item) {
      item.is_enabled = item.is_enabled === 1 ? 0 : 1
      this.updateProduct(item)
    },
    updateProductRating (item, rating) {
      item.eval = rating
      this.updateProduct(item)
    },
    updateProduct (item) {
      this.$emitter.emit('isAdminLoading', true)
      this.tempProduct = item
      let url = `${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/admin/product`
      let httpMethods = 'post'
      let status = '新增產品'
      if (!this.isNew) {
        url = `${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/admin/product/${this.tempProduct.id}`
        httpMethods = 'put'
        status = '更新產品'
      }
      this.$http[httpMethods](url, { data: this.tempProduct })
        .then((res) => {
          if (res.data.success) {
            this.$httpMessageState(res, status)
            const index = this.products.findIndex((product) => product.id === this.tempProduct.id)
            if (index !== -1) {
              // 更新現有產品
              this.products[index] = { ...this.tempProduct }
            } else if (this.isNew) {
              // 新增新產品
              this.tempProduct.id = res.data.pid
              this.products.push({ ...this.tempProduct })
            }
            this.updatePagination()
            this.back_show = false
            this.$refs.productModal.closeModal()
          }
        })
        .catch(err => {
          this.$httpMessageState(err.response, status)
        })
        .finally(() => {
          this.$emitter.emit('isAdminLoading', false)
        })
    },
    delProduct (id) {
      this.$emitter.emit('isAdminLoading', true)
      const url = `${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/admin/product/${id}`
      this.$http.delete(url)
        .then((res) => {
          if (res.data.success) {
            this.$httpMessageState(res, '刪除產品')

            const index = this.products.findIndex((product) => product.id === id)
            if (index !== -1) {
              this.products.splice(index, 1) // 刪除本地資料
              this.updatePagination()
            }

            this.back_show = false
            this.$refs.delModal.closeModal()
          }
        })
        .catch(err => {
          this.$httpMessageState(err.response, '刪除產品')
        })
        .finally(() => {
          this.$emitter.emit('isAdminLoading', false)
        })
    },
    openProductModal (isNew, item) {
      this.isNew = isNew
      this.tempProduct = isNew
        ? { is_enabled: 1, eval: 0, title: '', price: 0, origin_price: 0 }
        : { ...item }
      this.$refs.productModal.openModal()
    },
    openDelModal (type, item) {
      this.tempProduct = { ...item }
      this.back_show = true
      this.$refs.delModal.openModal(type)
    },
    closeAllModal () {
      this.back_show = false
      this.$refs.productModal.closeModal()
      this.$refs.delModal.closeModal()
    }
  },
  watch: {
    searchText: 'searchHandler'
  },
  mounted () {
    this.getProducts()
  }
}
</script>

<style lang="scss">
  .mobile-link {
    display: none;
    @media (max-width: 991px) {
      display: flex;
      gap: 40px;
      margin-bottom: 30px;
    }
    > a {
      padding: 10px 20px;
      text-align: center;
      background-color: #1A535C;
      span {
        color: #fff;
        font-size: 14px;
        font-weight: bold;
      }
    }
  }
</style>
